import type { Meta, StoryObj } from '@storybook/react-vite';
import type { FC } from 'react';
import { makeWindow, AppWithPickerOpen } from '../../../test/Storybook';
import type { FolderNode } from '@fde-desktop/fde-core';
import type { FileNode } from '@fde-desktop/fde-core';
import { VscIcon, DirtyIndicator } from '@fde-desktop/fde-core';
import classes from './NotesApp.module.css';

/* ── Shared nodes ─────────────────────────────────────────────────────── */

const notesFolder: FolderNode = {
  id: 'folder-notes',
  name: 'Notes',
  type: 'folder',
  parentId: null,
  children: ['file-welcome', 'file-todo'],
  createdAt: new Date(),
  updatedAt: new Date(),
};

const fileWelcome: FileNode = {
  id: 'file-welcome',
  name: 'welcome.md',
  type: 'file',
  parentId: 'folder-notes',
  content: `# Welcome to NotesApp

This is a **markdown** editor powered by [TipTap](https://tiptap.dev).

## Features

- Rich text editing
- *Italic*, **bold**, ~~strikethrough~~
- \`inline code\` and code blocks
- Bullet and ordered lists
- Blockquotes

> Write something great today.
`,
  mimeType: 'text/markdown',
  url: undefined,
  createdAt: new Date(),
  updatedAt: new Date(),
};

const fileTodo: FileNode = {
  id: 'file-todo',
  name: 'todo.md',
  type: 'file',
  parentId: 'folder-notes',
  content: `# TODO

- [ ] Buy groceries
- [ ] Write documentation
- [x] Set up NotesApp
`,
  mimeType: 'text/markdown',
  url: undefined,
  createdAt: new Date(),
  updatedAt: new Date(),
};

const fsNodes = [notesFolder, fileWelcome, fileTodo];

/* ── Toolbar Mock for Storybook Controls ───────────────────────────────── */

interface NotesAppToolbarProps {
  isDirty: boolean;
  canUndo: boolean;
  canRedo: boolean;
  isBold: boolean;
  isItalic: boolean;
  isStrike: boolean;
  isCode: boolean;
  isH1: boolean;
  isH2: boolean;
  isBulletList: boolean;
  isOrderedList: boolean;
  isBlockquote: boolean;
  isCodeBlock: boolean;
}

const MockToolbar: FC<NotesAppToolbarProps> = ({
  isDirty,
  canUndo,
  canRedo,
  isBold,
  isItalic,
  isStrike,
  isCode,
  isH1,
  isH2,
  isBulletList,
  isOrderedList,
  isBlockquote,
  isCodeBlock,
}) => (
  <div className={classes.container}>
    <div className={classes.toolbar} role="toolbar" aria-label="Text formatting">
      <button
        className={`${classes.toolbarBtn} ${isBold ? classes.active : ''}`}
        disabled={false}
        title="Bold"
        aria-label="Bold"
      >
        <VscIcon name="VscBold" />
      </button>
      <button
        className={`${classes.toolbarBtn} ${isItalic ? classes.active : ''}`}
        disabled={false}
        title="Italic"
        aria-label="Italic"
      >
        <VscIcon name="VscItalic" />
      </button>
      <button
        className={`${classes.toolbarBtn} ${isStrike ? classes.active : ''}`}
        disabled={false}
        title="Strikethrough"
        aria-label="Strikethrough"
      >
        <s>S</s>
      </button>
      <button
        className={`${classes.toolbarBtn} ${isCode ? classes.active : ''}`}
        disabled={false}
        title="Inline code"
        aria-label="Inline code"
      >
        <VscIcon name="VscCode" />
      </button>
      <span className={classes.separator} />
      <button
        className={`${classes.toolbarBtn} ${isH1 ? classes.active : ''}`}
        disabled={false}
        title="Heading 1"
        aria-label="Heading 1"
      >
        <strong>H1</strong>
      </button>
      <button
        className={`${classes.toolbarBtn} ${isH2 ? classes.active : ''}`}
        disabled={false}
        title="Heading 2"
        aria-label="Heading 2"
      >
        <strong>H2</strong>
      </button>
      <span className={classes.separator} />
      <button
        className={`${classes.toolbarBtn} ${isBulletList ? classes.active : ''}`}
        disabled={false}
        title="Bullet list"
        aria-label="Bullet list"
      >
        <VscIcon name="VscListUnordered" />
      </button>
      <button
        className={`${classes.toolbarBtn} ${isOrderedList ? classes.active : ''}`}
        disabled={false}
        title="Ordered list"
        aria-label="Ordered list"
      >
        <VscIcon name="VscListOrdered" />
      </button>
      <span className={classes.separator} />
      <button
        className={`${classes.toolbarBtn} ${isBlockquote ? classes.active : ''}`}
        disabled={false}
        title="Blockquote"
        aria-label="Blockquote"
      >
        <VscIcon name="VscQuote" />
      </button>
      <button
        className={`${classes.toolbarBtn} ${isCodeBlock ? classes.active : ''}`}
        disabled={false}
        title="Code block"
        aria-label="Code block"
      >
        <VscIcon name="VscTerminal" />
      </button>
      <button
        className={classes.toolbarBtn}
        disabled={false}
        title="Horizontal rule"
        aria-label="Horizontal rule"
      >
        <VscIcon name="VscHorizontalRule" />
      </button>
      <span className={classes.separator} />
      <button className={classes.toolbarBtn} disabled={!canUndo} title="Undo" aria-label="Undo">
        <VscIcon name="VscDiscard" />
      </button>
      <button className={classes.toolbarBtn} disabled={!canRedo} title="Redo" aria-label="Redo">
        <VscIcon name="VscRedo" />
      </button>
      {isDirty && (
        <span className={classes.dirtyIndicator} title="Unsaved changes">
          <DirtyIndicator />
        </span>
      )}
    </div>
    <div
      className={classes.editorContent}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'var(--mantine-color-dimmed)',
        fontSize: 14,
      }}
    >
      Use the controls in the Controls panel to toggle toolbar states
    </div>
  </div>
);

